-- ================================================================
-- Uzbekistan (UZ) ES/DE/FR translations, completing 494 (milestones),
-- 496 (deep-dive content) and 498 (the Uzbekistan story only) against
-- their English content. Separate migration file, so every deep-dive
-- translation row looks up its parent row via a JOIN on stable
-- identifying columns (country code / section / sort_order / stable
-- url), never via (SELECT MAX(id) ...) -- pattern reference: 491
-- (Qatar), 442 (Kazakhstan). milestone_translations and
-- story_translations have natural PKs (milestone_id / story_id), so
-- those rows are plain INSERT OR IGNORE statements keyed on the
-- hardcoded id strings from 494/498 -- no JOIN needed. INSERT OR
-- IGNORE throughout. The Azerbaijan story from 498 is deliberately
-- NOT translated here; it belongs with Azerbaijan's own translation
-- migration.
--
-- Kept unchanged across languages: proper nouns, institution and
-- product names (ESF, ETsP, ITSPU, EDO, AI SOLIQ, Soliq LLM, Yangi
-- Texnologiyalar, CCAMTAC, lex.uz, soliq.uz, gov.uz, Buxgalter.uz),
-- legal instrument numbers (Resolution 522, Resolution 489, Decree
-- UP-153, Law ZRU-1108, Law ZRU-891, Tax Code Articles 223 and 88),
-- currency codes (UZS, sum), percentages, technical standard names
-- (EN 16931, Peppol, JSON, XML, QR) and every emoji. Only the
-- surrounding prose is translated. Following the house style set by
-- 442 (KZT 4.325 / 10 000 MRP), numeric group separators are
-- localized per language -- the values themselves never change.
-- Dates are localized per language convention ("1 January 2020" ->
-- "1 de enero de 2020" es / "1. Januar 2020" de / "1er janvier 2020"
-- fr) but never shifted. The IMF is rendered with its usual
-- per-language name (FMI es, IWF de, FMI fr), matching existing
-- migrations; CCAMTAC is left as-is.
--
-- The page's deliberate editorial position -- that Uzbekistan is NOT
-- a pre-clearance regime, and that four research items are flagged
-- rather than settled -- is preserved with exactly the same hedging
-- in every language, never softened.
-- ================================================================


-- ==================== es ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es',
  'Control continuo de transacciones (CTC) centralizado: facturación electrónica B2B universal desde 2020, intercambiada a través de la plataforma estatal o de un operador registrado, con el comprador como puerta de validación — no es un régimen de clearance previo',
  'Esta página de análisis refleja la legislación uzbeka publicada en lex.uz y en el propio portal del Comité Estatal de Impuestos (gov.uz), complementada con la prensa especializada uzbeka en materia jurídica y tributaria allí donde no fue posible recuperar íntegramente los anexos primarios, con fecha de 10 de agosto de 2026. Se ofrece a título informativo general, no como asesoría legal o tributaria. Varios elementos se señalan expresamente en esta página como no confirmados en lugar de presentarse como hechos establecidos — le rogamos que lea esas notas. Confirme los requisitos vigentes directamente con el Comité de Impuestos de Uzbekistán, con su operador ESF o con un asesor fiscal uzbeko antes de basar en esta página sus decisiones de cumplimiento.',
  'El régimen de factura electrónica ESF de Uzbekistán fue creado por la Resolución del Consejo de Ministros N.º 522, de 25 de junio de 2019: voluntario desde el 1 de julio de 2019 y obligatorio para todas las entidades empresariales desde el 1 de enero de 2020. La Resolución N.º 489, de agosto de 2020, fijó las reglas operativas que siguen vigentes. El 1 de enero de 2026 llegaron dos cambios — la puntuación de riesgo de las facturas en tiempo real y la extensión de la obligación a los trabajadores autónomos.',
  'Una factura electrónica uzbeka conforme es un documento electrónico estructurado, firmado por el vendedor con una firma digital ETsP y refrendado por el comprador en el momento de la aceptación. Se intercambia bien a través de la plataforma estatal, bien a través de cualquiera de los operadores privados EDO registrados, y la interoperabilidad entre operadores corre a cargo del operador de roaming designado por el Estado, la empresa estatal "Yangi Texnologiyalar". Las líneas de productos y servicios llevan códigos de clasificación ITSPU tomados del catálogo electrónico nacional.',
  'La obligación es universal para las entidades empresariales y no está vinculada al umbral del IVA: toda entidad económica debe emitir facturas electrónicas, sea o no contribuyente del IVA. Los trabajadores autónomos quedaron incluidos desde el 1 de enero de 2026. Las facturas en papel solo subsisten cuando la operación afecta a secretos de Estado. Las ventas a consumidores particulares quedan en la práctica fuera del circuito de intercambio electrónico y están cubiertas en su lugar por las cajas registradoras en línea.',
  'Si comercia en régimen B2B en Uzbekistán, ya está dentro del alcance y lo está desde 2020 — no queda ninguna fase de implantación para la que prepararse. El trabajo vivo consiste en adaptarse a los dos cambios de enero de 2026: el sistema de puntuación de riesgo, que afecta al momento en que sus compradores pueden recuperar el IVA soportado de sus facturas, y las declaraciones precumplimentadas que se generan a partir de su propio flujo de facturas.',
  'Uzbekistán respalda el mandato con una única sanción cuantificada — el 20 % de la base imponible ocultada, conforme al artículo 223 del Código Tributario — en lugar de con un cuadro publicado de multas de importe fijo. El sistema de puntuación de riesgo de 2026 no lleva aparejada sanción alguna; su consecuencia es el aplazamiento del crédito de IVA soportado del comprador.',
  'Uzbekistán exige facturas electrónicas a todas las entidades empresariales desde el 1 de enero de 2020, en virtud de la Resolución del Consejo de Ministros N.º 522. Las facturas se intercambian a través de la plataforma estatal o de un operador privado registrado, las firma digitalmente el vendedor y las confirma el comprador en un plazo de diez días. Desde el 1 de enero de 2026 cada factura recibe una puntuación de riesgo en tiempo real, el IVA soportado de una factura marcada solo es deducible una vez que el impuesto llega al presupuesto, y la autoridad fiscal precumplimenta ahora las declaraciones de IVA directamente a partir del flujo de facturas.',
  '🇺🇿'
FROM countries WHERE code = 'UZ';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 ene 2020', 'La facturación electrónica se vuelve obligatoria para todas las entidades empresariales' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'UZ' AND s.sort_order = 0;
