INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '27', 'Operadores ESF inscritos en el registro del Comité de Impuestos (enero de 2026)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'UZ' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '209.000', 'Contribuyentes del IVA, cifra citada en la reunión presidencial sobre fiscalidad de abril de 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'UZ' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '12 %', 'Tasa estándar del IVA, con una tasa simplificada opcional del 6 % desde junio de 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'UZ' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Formato y transmisión', '[["Formato de la factura", "Documento electrónico estructurado, del que se informa que es JSON"], ["Firma", "Firma digital ETsP — bilateral: el vendedor firma para emitir, el comprador firma para aceptar"], ["Canales", "La plataforma estatal, o cualquiera de los 27 operadores privados EDO registrados"], ["Interoperabilidad", "A cargo del operador de roaming designado por el Estado, la empresa estatal \"Yangi Texnologiyalar\" (Resolución 522)"], ["Códigos de clasificación", "Códigos ITSPU del catálogo electrónico nacional, que contenía más de 454.500 códigos en septiembre de 2024"], ["Normas europeas", "No es EN 16931; Uzbekistán no es una autoridad Peppol"]]', 'El formato JSON se afirma de manera coherente en varias fuentes secundarias independientes, pero en esta ronda de investigación no se localizó ninguna especificación técnica primaria — trate el nombre del formato como bien respaldado, no como confirmado.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Conservación: dos relojes distintos', '[["Operadores", "Deben conservar los documentos electrónicos confirmados durante al menos 5 años, tras lo cual el archivo pasa a la autoridad fiscal"], ["Contribuyentes", "La conservación general de documentos contables y tributarios se redujo de 5 a 3 años desde el 1 de enero de 2024 por la Ley N.º ZRU-891, siguiendo el plazo de prescripción del artículo 88 del Código Tributario"], ["Plazos más largos", "Los registros de activos fijos y de amortizaciones se conservan durante más tiempo"]]', 'Se trata de obligaciones realmente distintas que con frecuencia se confunden. Que su operador conserve una factura durante cinco años no amplía su propio deber de conservación de tres años, y ese deber de tres años tampoco acorta el del operador.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Quién debe emitir facturas electrónicas', '[["Todas las entidades empresariales", "Obligatorio desde el 1 de enero de 2020 en virtud de la Resolución 522 — sin umbral de ingresos sobre la propia obligación"], ["Trabajadores autónomos", "Incluidos desde el 1 de enero de 2026 por la Ley N.º ZRU-1108, en pie de igualdad con las personas jurídicas y los empresarios individuales"], ["B2G", "Dentro del alcance"], ["B2C", "En la práctica no es un intercambio electrónico — véase la nota"], ["Única exención encontrada", "Operaciones que afectan a secretos de Estado, en las que siguen permitiéndose facturas en papel en al menos dos ejemplares"]]', 'El alcance B2C es objeto de auténtica discrepancia. Dos fuentes internacionales de cumplimiento incluyen el B2C dentro del alcance, pero la guía de los profesionales uzbekos indica que, en las ventas a consumidores particulares, el vendedor imprime y entrega el documento, sin que se aplique el circuito electrónico — el comercio minorista queda cubierto en su lugar por las cajas registradoras en línea y las obligaciones de pago mediante código QR. Esta página no afirma que exista un mandato de facturación electrónica B2C.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🔍 Por qué esta página no califica a Uzbekistán como régimen de clearance', NULL, NULL, 'Un folleto sectorial de amplia difusión describe Uzbekistán como un modelo de clearance en tiempo real en el que la autoridad fiscal valida la factura antes de que esta adquiera validez jurídica definitiva. Las pruebas apuntan en otra dirección, de modo que esta página lo describe de otro modo y explica por qué. El flujo documentado va del vendedor al comprador, no del vendedor a la autoridad fiscal y de esta al comprador: el vendedor firma y transmite, y a continuación el comprador certifica con su propia firma o rechaza indicando los motivos, dentro de una ventana de diez días transcurrida la cual se desactiva la opción de rechazo. Un plazo de aceptación del comprador es la seña de identidad de un modelo de intercambio. El sistema de riesgo de 2026 refuerza esa idea: colorea las facturas en lugar de bloquearlas, y una factura marcada sigue estando válidamente emitida, con la consecuencia recayendo sobre el momento de deducción del IVA soportado del comprador y no sobre la validez de la factura. Bajo un verdadero clearance previo, una factura rechazada sencillamente no existiría. Existe una puerta técnica de registro y, desde 2026, una puerta de riesgo que afecta al crédito de IVA, pero no una puerta de aprobación fiscal que suspenda la validez jurídica a la espera del visto bueno de la autoridad. Una salvedad más, declarada en lugar de escondida: el Anexo 2 de la Resolución 489, que contiene el procedimiento operativo, no pudo recuperarse íntegramente de una fuente primaria en esta ronda de investigación, por lo que la descripción del flujo anterior se apoya en prensa jurídica especializada uzbeka de alta calidad y no en el texto legal.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'El flujo de intercambio', 'Una factura electrónica uzbeka recorre la siguiente secuencia:', 'El paso decisivo es el del comprador, no el de la autoridad fiscal — razón por la cual esta página describe a Uzbekistán como un intercambio centralizado y no como un régimen de clearance.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND lc.section = 'scope_transmission' AND lc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'El vendedor genera la factura y la firma con una firma digital ETsP' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND ls.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'Se transmite a través de la plataforma estatal o de un operador registrado, con enrutamiento entre operadores a través del operador estatal de roaming' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'Desde 2026: recibe una puntuación de riesgo en tiempo real y queda marcada, pero no se bloquea' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'El comprador certifica con su propia firma, o rechaza indicando los motivos, en un plazo de 10 días' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'Los bienes con marcado digital corren un reloj mucho más corto: confirmar o rechazar en el plazo de un día natural, o la factura se confirma automáticamente' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND ls.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '⚠️ La única sanción cuantificada: artículo 223 del Código Tributario', NULL, NULL, 'Uzbekistán no publica un cuadro de multas de importe fijo por incumplimientos de formato, transmisión o aceptación en materia de facturación electrónica. Tiene una única sanción cuantificada, y es contundente: el 20 % de la base imponible ocultada o infradeclarada, conforme al artículo 223 del Código Tributario, aplicable cuando se venden bienes o servicios sin emitir una factura electrónica, o cuando esta se emite fuera de plazo. La aplicación comenzó el 1 de abril de 2021, aplazada desde el 1 de marzo, y a partir de esa fecha los contribuyentes solo podían emitir con carácter retroactivo facturas de periodos anteriores asumiendo el recargo del 20 %. Un matiz que conviene conocer: los profesionales tributarios uzbekos sostienen que el artículo 223 es una norma sobre ocultación y no sobre formalidades documentales, y que por tanto no debería aplicarse cuando la factura se emite lícitamente después del cierre del mes dentro de los plazos de la Resolución 489, puesto que no se produce distorsión tributaria alguna. La cifra del 20 % está corroborada por dos fuentes uzbekas independientes, pero el texto literal del artículo no pudo leerse directamente en esta ronda de investigación — lex.uz sirve el Código Tributario como un único documento muy extenso que no llegaba a mostrar el cuerpo del artículo.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🚦 Puntuación de riesgo: sin multa, pero su comprador lo paga en tesorería', NULL, NULL, 'El sistema que entró en funcionamiento el 1 de enero de 2026 en virtud del artículo 4 del Decreto Presidencial UP-153 no lleva aparejada sanción alguna, lo que hace fácil subestimarlo. Cada factura se puntúa en tiempo real frente a criterios que el Comité de Impuestos ha mantenido deliberadamente en secreto — según se informa, 48 de ellos, no divulgados siguiendo el consejo de expertos internacionales para impedir que se juegue con el sistema — y se marca en rojo o en verde, con el estado visible para el comprador. De ahí se derivan dos consecuencias. Las facturas marcadas de un contribuyente no pueden superar el 10 % de todas las facturas emitidas en un periodo de declaración. Y el IVA soportado de una factura marcada solo pasa a ser deducible una vez que el impuesto ha sido efectivamente ingresado en el presupuesto por el vendedor o por el comprador, lo que en la práctica empuja a los compradores a esperar a su proveedor o a pagar ellos mismos el IVA. El efecto comercial es que su situación de riesgo se convierte en un problema para sus clientes y, por lo tanto, en un problema para usted. Cifras del piloto citadas en el lanzamiento: 281 empresas, 5,9 billones de sum en facturas y 706.000 millones de sum de crédito de IVA en juego entre julio y septiembre de 2025.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '💳 Sanciones adyacentes de 2026, y lo que no pudimos confirmar', NULL, NULL, 'La Ley ZRU-1108 introdujo desde el 1 de enero de 2026 dos multas adyacentes que no son sanciones de facturación electrónica, pero que están lo bastante cerca como para merecer atención: UZS 5.000.000 por operar sin los sistemas de pago electrónico y los códigos QR obligatorios, y UZS 20.000.000 por utilizar los códigos QR de otro contribuyente. Ambas proceden de la alerta de una firma de servicios profesionales y no del texto legal. Cuatro elementos de esta ronda de investigación se señalan en lugar de presentarse como hechos establecidos: no pudo leerse el texto literal del artículo 223 del Código Tributario; no pudo recuperarse íntegramente el Anexo 2 de la Resolución 489, que es el reglamento de procedimiento operativo; el formato de factura JSON se apoya en fuentes secundarias coherentes sin que se haya localizado ninguna especificación técnica primaria; y los dos sitios web de soliq.uz están bloqueados a la comprobación automatizada mediante robots, por lo que su disponibilidad actual no se verificó de forma independiente.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme que efectivamente está emitiendo facturas electrónicas', 'La obligación es universal para las entidades empresariales y lo es desde el 1 de enero de 2020 — no hay ningún umbral por debajo del cual quedar exento ni ninguna fase de implantación pendiente. Si alguna parte de su actividad uzbeka sigue en papel, eso es una exposición viva conforme al artículo 223, no un plazo futuro.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'UZ' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Obtenga una firma digital ETsP y elija un canal', 'Necesita un certificado de firma digital del centro de claves de la autoridad fiscal y, o bien una cuenta en la plataforma estatal, o bien una cuenta con uno de los 27 operadores registrados. Como el operador estatal de roaming enruta entre operadores, elegir uno privado no le deja incomunicado con ninguna contraparte.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'UZ' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Incorpore la ventana de aceptación del comprador a su propio proceso', 'El comprador dispone de diez días para certificar o rechazar y, una vez transcurridos, la opción de rechazo se desactiva y usted ya no puede anular la factura. Las facturas de bienes con marcado digital corren un reloj de un día con confirmación automática. Persiga la aceptación en lugar de dar por hecho que el silencio equivale a conformidad.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'UZ' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Trate su situación de riesgo como una cuestión comercial, no solo tributaria', 'Desde enero de 2026 sus facturas se puntúan y se marcan, y una factura marcada retrasa la recuperación del IVA soportado de su cliente. Vigile su proporción de facturas marcadas frente al techo del 10 % y espere que los compradores empiecen a preguntar por ella. Los criterios son secretos por diseño, de modo que la diligencia debida sobre proveedores y contrapartes es el único control real.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'UZ' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Revise la declaración de IVA precumplimentada en un plazo de cinco días hábiles', 'Desde enero de 2026 la autoridad fiscal genera sus declaraciones de IVA y del impuesto sobre el volumen de negocios a partir de su propio flujo de facturas, y usted dispone de cinco días hábiles para corregirlas. Concilie de forma continua en lugar de hacerlo en el momento de la presentación — cuando aparece la declaración, los datos subyacentes ya son la versión de los hechos que tiene la autoridad.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'UZ' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'Comité Estatal de Impuestos — portal oficial (gov.uz)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'UZ' AND pt.url = 'https://gov.uz/en/soliq';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'lex.uz — Resolución N.º 522, de 25 de junio de 2019, el instrumento fundacional' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'UZ' AND pt.url = 'https://lex.uz/en/docs/4386771';

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'uz-res-522-2019', 'es',
  'La Resolución del Consejo de Ministros N.º 522 establece el régimen de factura electrónica ESF',
  'La Resolución N.º 522, de 25 de junio de 2019, "Sobre medidas para mejorar el uso de las facturas electrónicas en el sistema de liquidaciones mutuas", es el instrumento fundacional del régimen de factura electrónica (ESF / электрон счёт-фактура) de Uzbekistán. Su texto establece la facturación electrónica como voluntaria desde el 1 de julio de 2019 y obligatoria desde el 1 de enero de 2020 para todas las entidades empresariales. También designa a la empresa estatal "Yangi Texnologiyalar" (Nuevas Tecnologías), dependiente de la autoridad fiscal, como operador de roaming autorizado, responsable del almacenamiento centralizado y de la transmisión entre operadores privados competidores — el nodo que hace que el modelo multioperador de Uzbekistán sea interoperable en lugar de fragmentado.',
  '["Hoy no se requiere ninguna acción — este es el fundamento jurídico histórico, citado para que el mandato de 2020 tenga un origen rastreable", "Si necesita el texto operativo, lex.uz publica la Resolución 522 en ruso con una portada en inglés"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'uz-mandate-2020', 'es',
  'La facturación electrónica pasa a ser obligatoria para todas las entidades empresariales',
  'Desde el 1 de enero de 2020, las facturas electrónicas son obligatorias para todas las entidades económicas de Uzbekistán, tras una fase voluntaria de seis meses iniciada el 1 de julio de 2019. Esta es la fecha ancla del mandato de Uzbekistán y la razón por la que el país figura en este rastreador: una obligación de facturación electrónica B2B universal y de ámbito nacional que lleva más de seis años en vigor. Las facturas se intercambian a través del sistema estatal o de cualquiera de los operadores privados registrados, las firma el vendedor con una firma digital (ETsP) y a continuación las confirma o rechaza el comprador, que también firma. Las facturas en papel solo sobreviven en operaciones que afectan a secretos de Estado.',
  '["Si comercia en régimen B2B en Uzbekistán ya está dentro del alcance — no existe ningún umbral de ingresos sobre la propia obligación de facturación electrónica", "Obtenga un certificado de firma digital ETsP a través del centro de claves de la autoridad fiscal", "Elija entre la plataforma estatal y un operador privado registrado — la interoperabilidad entre ambos la gestiona el operador estatal de roaming, de modo que la elección no le deja fuera del alcance de ninguna contraparte"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'uz-res-489-2020', 'es',
  'La Resolución N.º 489 fija las reglas operativas: los plazos de emisión y la ventana de 10 días del comprador',
  'La Resolución del Consejo de Ministros N.º 489, de 14 de agosto de 2020, contiene, en su Anexo 2, la reglamentación que rige realmente la práctica diaria del ESF: la forma de la factura y el modo en que se cumplimenta, se presenta y se acepta. Fija la regla general de que la factura lleva la fecha del día del envío o de la prestación del servicio, la regla mensual especial para los suministros continuados (emisión antes del día 10 del mes siguiente) y la ventana de 10 días de que dispone el comprador para aceptar o rechazar. Nota para quien contraste esto con los comentarios del sector: la regla del "día 10" se atribuye con frecuencia y erróneamente a una resolución de 2025 — su origen está aquí, en 2020.',
  '["Incorpore la ventana de aceptación de 10 días del comprador a su proceso — una vez transcurrida, la opción de rechazo se desactiva y el vendedor ya no puede anular la factura", "Las facturas de bienes con marcado digital corren un reloj mucho más corto: confirme o rechace en el plazo de un día natural, o el sistema confirma automáticamente"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'uz-risk-scoring-2026', 'es',
  'Comienza el análisis de riesgo automatizado y en tiempo real de todas las facturas electrónicas',
  'El artículo 4 del Decreto Presidencial N.º UP-153, de 4 de septiembre de 2025, ordenó al Comité de Impuestos desplegar, desde el 1 de enero de 2026, un análisis de riesgo automatizado y en tiempo real de todas las facturas electrónicas emitidas en Uzbekistán. Las facturas se puntúan frente a criterios no divulgados y se marcan; de ello se derivan dos consecuencias. Las facturas de alto riesgo no pueden superar el 10 % del total de facturas que un contribuyente emite en un periodo de declaración, y el IVA soportado de una factura de alto riesgo solo pasa a ser deducible una vez que el impuesto ha sido efectivamente ingresado en el presupuesto por el vendedor o por el comprador. El sistema se desarrolló con asistencia técnica del FMI y del CCAMTAC. Es importante señalar que no bloquea las facturas: una factura marcada sigue estando válidamente emitida, y la consecuencia recae sobre el momento de deducción del IVA del comprador.',
  '["Compradores: comprueben la situación de riesgo de las facturas recibidas antes de confiar en el crédito de IVA soportado — una factura marcada aplaza la recuperación, no la deniega", "Vendedores: vigilen su propia proporción de facturas marcadas frente al techo del 10 %", "Los criterios no se publican deliberadamente, de modo que esto no puede sortearse con ingeniería — trate la diligencia debida sobre proveedores como el verdadero control"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'uz-self-employed-2026', 'es',
  'Los trabajadores autónomos entran en la obligación de facturación; las declaraciones se precumplimentan con los datos de las facturas',
  'La Ley N.º ZRU-1108, de 25 de diciembre de 2025, en vigor desde el 1 de enero de 2026, extiende la obligación de facturación a los trabajadores autónomos en pie de igualdad con las personas jurídicas y los empresarios individuales — una ampliación genuina de quién debe emitir. La misma ley introduce algo posiblemente más relevante: la autoridad fiscal genera ahora automáticamente las declaraciones del IVA y del impuesto sobre el volumen de negocios a partir de los datos ESF, y concede a los contribuyentes cinco días hábiles para corregirlas. Ese es el punto en el que el flujo de facturas de Uzbekistán deja de ser un artefacto de cumplimiento y se convierte en la propia declaración.',
  '["Trabajadores autónomos que operen con empresas: ya están dentro del alcance y necesitan una firma digital y una cuenta con un operador o en la plataforma estatal", "Todos los contribuyentes: revisen la declaración de IVA precumplimentada dentro de los cinco días hábiles concedidos — el silencio es aceptación", "Concilie sus propios libros con el flujo de facturas de forma continua y no en el momento de la presentación, ya que ahora es el flujo el que determina la declaración"]'
);

INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES (
  '2026-07-29-uzbekistan-ai-soliq', 'es',
  'Uzbekistán construye un chatbot para explicar las puntuaciones de riesgo de las facturas que no piensa publicar',
  'El Comité de Impuestos de Uzbekistán ha lanzado AI SOLIQ, una plataforma de inteligencia artificial construida sobre su propio modelo "Soliq LLM". Su función más trascendental para las empresas: los contribuyentes pueden ahora preguntar al sistema por qué una factura electrónica concreta fue marcada como de alto riesgo bajo el régimen de puntuación en tiempo real que entró en funcionamiento en enero de 2026 — criterios que, por lo demás, se mantienen deliberadamente sin publicar.',
  '<h3>🇺🇿 Uzbekistán construye un chatbot para explicar las puntuaciones de riesgo de las facturas que no piensa publicar</h3>
<p>El 29 de julio de 2026, el Comité de Impuestos de Uzbekistán presentó AI SOLIQ, una plataforma unificada de inteligencia artificial construida sobre "Soliq LLM", su propio modelo lingüístico, con componentes de generación de texto y voz, visión artificial y aprendizaje automático.</p>
<p>La función que más importa a quien comercia en Uzbekistán es más estrecha de lo que sugiere la presentación del lanzamiento. Desde el 1 de enero de 2026, cada factura electrónica emitida en el país recibe una puntuación de riesgo en tiempo real y se marca en rojo o en verde, en virtud del artículo 4 del Decreto Presidencial UP-153. Los criterios — según se informa, 48 de ellos — se mantienen deliberadamente reservados, siguiendo el consejo de expertos internacionales, para impedir que los contribuyentes jueguen con el sistema. Ese secretismo es defendible como política antielusión e incómodo como atención al cliente: una empresa podía ver una factura marcada sin manera alguna de averiguar por qué.</p>
<p>AI SOLIQ es la respuesta a eso. Los contribuyentes pueden ahora mantener un diálogo con el sistema sobre por qué una factura concreta se clasificó en rojo, junto con explicaciones de su calificación fiscal y de sus obligaciones de presentación. Lo que está en juego es real y no meramente reputacional: el IVA soportado de una factura marcada solo pasa a ser deducible una vez que el impuesto ha llegado efectivamente al presupuesto, de modo que la situación de riesgo de un proveedor retrasa directamente la tesorería de sus clientes.</p>
<p>Es una secuencia llamativa — una administración tributaria que primero hizo que el riesgo de las facturas fuera consecuente e inexplicado, y después construyó un modelo lingüístico para explicarlo — y merece seguimiento a medida que otras jurisdicciones de clearance y CTC añaden sus propias capas de puntuación.</p>'
);


-- ==================== de ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de',
  'Zentralisierte kontinuierliche Transaktionskontrolle (CTC): universelle B2B-E-Rechnungsstellung seit 2020, ausgetauscht über die staatliche Plattform oder einen registrierten Betreiber, wobei der Käufer die Validierungsinstanz ist — kein Vorabfreigabesystem',
  'Diese Analyseseite gibt die usbekische Gesetzgebung wieder, wie sie auf lex.uz und auf dem eigenen Portal des Staatlichen Steuerkomitees (gov.uz) veröffentlicht ist, ergänzt durch die usbekische Fachpresse zu Rechts- und Steuerfragen dort, wo primäre Anhänge nicht vollständig abgerufen werden konnten, mit Stand vom 10. August 2026. Sie dient der allgemeinen Information und stellt keine Rechts- oder Steuerberatung dar. Mehrere Punkte werden auf dieser Seite ausdrücklich als unbestätigt gekennzeichnet, statt als gesichert dargestellt zu werden — bitte lesen Sie diese Hinweise. Bestätigen Sie die aktuellen Anforderungen direkt beim usbekischen Steuerkomitee, bei Ihrem ESF-Betreiber oder bei einem usbekischen Steuerberater, bevor Sie sich bei Compliance-Entscheidungen auf diese Seite verlassen.',
  'Usbekistans elektronisches Rechnungssystem ESF wurde durch die Verordnung des Ministerkabinetts Nr. 522 vom 25. Juni 2019 geschaffen: freiwillig ab dem 1. Juli 2019, verpflichtend für alle Unternehmen ab dem 1. Januar 2020. Die Verordnung Nr. 489 vom August 2020 legte die bis heute geltenden Betriebsregeln fest. Zum 1. Januar 2026 kamen zwei Änderungen hinzu — die Risikobewertung von Rechnungen in Echtzeit und die Ausweitung der Pflicht auf Selbstständige.',
  'Eine konforme usbekische E-Rechnung ist ein strukturiertes elektronisches Dokument, das vom Verkäufer mit einer digitalen ETsP-Signatur unterzeichnet und vom Käufer bei der Annahme gegengezeichnet wird. Der Austausch erfolgt entweder über die staatliche Plattform oder über einen der registrierten privaten EDO-Betreiber, wobei die Interoperabilität zwischen den Betreibern vom staatlich benannten Roaming-Betreiber übernommen wird, dem Staatsunternehmen „Yangi Texnologiyalar". Waren- und Dienstleistungspositionen tragen ITSPU-Klassifizierungscodes aus dem nationalen E-Katalog.',
  'Die Pflicht gilt universell für Unternehmen und ist nicht an die MwSt-Schwelle gekoppelt: Jede wirtschaftliche Einheit muss elektronische Rechnungen ausstellen, unabhängig davon, ob sie mehrwertsteuerpflichtig ist. Selbstständige wurden zum 1. Januar 2026 einbezogen. Papierrechnungen bestehen nur dort fort, wo ein Geschäft Staatsgeheimnisse berührt. Verkäufe an private Verbraucher liegen in der Praxis außerhalb des elektronischen Austauschkreislaufs und werden stattdessen über Online-Registrierkassen abgedeckt.',
  'Wenn Sie in Usbekistan B2B handeln, fallen Sie bereits seit 2020 in den Anwendungsbereich — es steht keine Einführungsphase mehr bevor, auf die Sie sich vorbereiten müssten. Die eigentliche Arbeit besteht in der Anpassung an die beiden Änderungen vom Januar 2026: das Risikobewertungssystem, das beeinflusst, wann Ihre Käufer die Vorsteuer aus Ihren Rechnungen geltend machen können, und die aus Ihrem eigenen Rechnungsstrom vorausgefüllten Steuererklärungen.',
  'Usbekistan flankiert das Mandat mit einer einzigen bezifferten Sanktion — 20 % der verheimlichten Bemessungsgrundlage nach Artikel 223 des Steuergesetzbuchs — statt mit einem veröffentlichten Katalog fester Bußgelder. Das Risikobewertungssystem von 2026 sieht überhaupt keine Strafe vor; seine Folge ist der Aufschub des Vorsteuerabzugs beim Käufer.',
  'Usbekistan verlangt seit dem 1. Januar 2020 von allen Unternehmen elektronische Rechnungen, gestützt auf die Verordnung des Ministerkabinetts Nr. 522. Rechnungen werden über die staatliche Plattform oder einen registrierten privaten Betreiber ausgetauscht, vom Verkäufer digital signiert und vom Käufer innerhalb von zehn Tagen bestätigt. Seit dem 1. Januar 2026 wird jede Rechnung in Echtzeit auf Risiken bewertet, die Vorsteuer aus einer markierten Rechnung ist erst abziehbar, sobald die Steuer im Haushalt eingegangen ist, und die Steuerbehörde füllt die Umsatzsteuererklärungen nun direkt aus dem Rechnungsstrom vor.',
  '🇺🇿'
FROM countries WHERE code = 'UZ';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Jan. 2020', 'Die elektronische Rechnungsstellung wird für alle Unternehmen verpflichtend' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'UZ' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '~3,5 Millionen', 'Monatlich ausgestellte elektronische Rechnungen (gemeldet im Oktober 2025)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'UZ' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '27', 'Registrierte ESF-Betreiber im Register des Steuerkomitees (Januar 2026)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'UZ' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '209.000', 'Mehrwertsteuerpflichtige, genannt bei der Präsidialsitzung zum Steuerwesen im April 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'UZ' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '12 %', 'MwSt-Regelsatz, mit einem optionalen vereinfachten Satz von 6 % ab Juni 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'UZ' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Format und Übermittlung', '[["Rechnungsformat", "Strukturiertes elektronisches Dokument, Berichten zufolge JSON"], ["Signatur", "Digitale ETsP-Signatur — beidseitig: der Verkäufer signiert zur Ausstellung, der Käufer signiert zur Annahme"], ["Kanäle", "Die staatliche Plattform oder einer von 27 registrierten privaten EDO-Betreibern"], ["Interoperabilität", "Übernommen vom staatlich benannten Roaming-Betreiber, dem Staatsunternehmen \"Yangi Texnologiyalar\" (Verordnung 522)"], ["Klassifizierungscodes", "ITSPU-Codes aus dem nationalen E-Katalog, der im September 2024 über 454.500 Codes umfasste"], ["Europäische Normen", "Nicht EN 16931; Usbekistan ist keine Peppol-Behörde"]]', 'Das JSON-Format wird von unabhängigen Sekundärquellen übereinstimmend genannt, doch in dieser Rechercherunde konnte keine primäre technische Spezifikation gefunden werden — behandeln Sie die Formatangabe als gut belegt, nicht als bestätigt.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Aufbewahrung: zwei unterschiedliche Fristen', '[["Betreiber", "Müssen bestätigte elektronische Dokumente mindestens 5 Jahre aufbewahren; danach geht die Archivierung an die Steuerbehörde über"], ["Steuerpflichtige", "Die allgemeine Aufbewahrungsfrist für Buchführungs- und Steuerunterlagen wurde zum 1. Januar 2024 durch das Gesetz Nr. ZRU-891 von 5 auf 3 Jahre verkürzt, im Gleichlauf mit der Verjährungsfrist des Artikels 88 des Steuergesetzbuchs"], ["Längere Fristen", "Unterlagen zu Anlagevermögen und Abschreibungen werden länger aufbewahrt"]]', 'Dies sind tatsächlich getrennte Pflichten, die häufig vermischt werden. Dass Ihr Betreiber eine Rechnung fünf Jahre aufbewahrt, verlängert Ihre eigene dreijährige Aufbewahrungspflicht nicht, und Ihre dreijährige Pflicht verkürzt die seine nicht.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Wer elektronische Rechnungen ausstellen muss', '[["Alle Unternehmen", "Verpflichtend seit dem 1. Januar 2020 nach der Verordnung 522 — keine Umsatzschwelle für die Pflicht selbst"], ["Selbstständige", "Ab dem 1. Januar 2026 durch das Gesetz Nr. ZRU-1108 einbezogen, gleichgestellt mit juristischen Personen und Einzelunternehmern"], ["B2G", "Im Anwendungsbereich"], ["B2C", "In der Praxis kein elektronischer Austausch — siehe den Hinweis"], ["Einzige gefundene Ausnahme", "Geschäfte, die Staatsgeheimnisse berühren; hier bleiben Papierrechnungen in mindestens zwei Ausfertigungen zulässig"]]', 'Der B2C-Anwendungsbereich ist wirklich umstritten. Zwei internationale Compliance-Quellen führen B2C als erfasst auf, während usbekische Praktikerhinweise festhalten, dass der Verkäufer bei Verkäufen an private Verbraucher das Dokument ausdruckt und übergibt und der elektronische Kreislauf nicht greift — der Einzelhandel wird stattdessen über Online-Registrierkassen und QR-Code-Zahlungspflichten abgedeckt. Diese Seite behauptet keine B2C-E-Rechnungspflicht.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🔍 Warum diese Seite Usbekistan nicht als Freigabesystem bezeichnet', NULL, NULL, 'Eine weit verbreitete Branchenbroschüre beschreibt Usbekistan als Echtzeit-Freigabemodell, bei dem die Steuerbehörde eine Rechnung validiert, bevor sie rechtlich endgültig wird. Die Belege weisen in eine andere Richtung, daher beschreibt diese Seite es anders und erklärt, warum. Der dokumentierte Ablauf führt vom Verkäufer zum Käufer, nicht vom Verkäufer über die Steuerbehörde zum Käufer: Der Verkäufer signiert und übermittelt, danach bestätigt der Käufer mit seiner eigenen Signatur oder weist die Rechnung unter Angabe von Gründen zurück, und zwar innerhalb einer Frist von zehn Tagen, nach deren Ablauf die Zurückweisung nicht mehr möglich ist. Eine Annahmefrist für den Käufer ist das Kennzeichen eines Austauschmodells. Das Risikosystem von 2026 unterstreicht dies — es färbt Rechnungen ein, statt sie zu blockieren, und eine markierte Rechnung ist weiterhin wirksam ausgestellt, wobei die Folge den Zeitpunkt des Vorsteuerabzugs beim Käufer trifft und nicht die Gültigkeit der Rechnung. Bei einer echten Vorabfreigabe würde eine gescheiterte Rechnung überhaupt nicht existieren. Es gibt eine technische Registrierungsschwelle und seit 2026 eine Risikoschwelle mit Wirkung auf den Vorsteuerabzug, aber keine steuerliche Freigabeschwelle, die die Rechtswirksamkeit bis zur Zustimmung der Steuerbehörde aussetzt. Ein weiterer Vorbehalt, ausgesprochen statt versteckt: Anhang 2 zur Verordnung 489, der das maßgebliche Verfahren enthält, konnte in dieser Rechercherunde nicht vollständig aus einer Primärquelle abgerufen werden; die obige Ablaufbeschreibung stützt sich daher auf hochwertige usbekische juristische Fachpresse und nicht auf den Gesetzestext.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Der Austauschablauf', 'Eine usbekische elektronische Rechnung durchläuft diese Abfolge:', 'Der entscheidende Schritt liegt beim Käufer, nicht bei der Steuerbehörde — deshalb beschreibt diese Seite Usbekistan als zentralisierten Austausch und nicht als Freigabesystem.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND lc.section = 'scope_transmission' AND lc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Der Verkäufer erstellt die Rechnung und signiert sie mit einer digitalen ETsP-Signatur' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND ls.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Übermittlung über die staatliche Plattform oder einen registrierten Betreiber, mit betreiberübergreifendem Routing über den staatlichen Roaming-Betreiber' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Ab 2026: Bewertung des Risikos in Echtzeit und Markierung, jedoch keine Blockade' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Der Käufer bestätigt mit seiner eigenen Signatur oder weist die Rechnung unter Angabe von Gründen innerhalb von 10 Tagen zurück' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Für digital gekennzeichnete Waren gilt eine deutlich kürzere Frist: Bestätigung oder Zurückweisung innerhalb eines Kalendertages, sonst wird die Rechnung automatisch bestätigt' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND ls.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '⚠️ Die eine bezifferte Sanktion: Artikel 223 des Steuergesetzbuchs', NULL, NULL, 'Usbekistan veröffentlicht keinen Katalog fester Bußgelder für Verstöße gegen Format-, Übermittlungs- oder Annahmevorgaben bei der E-Rechnungsstellung. Es gibt eine einzige bezifferte Sanktion, und sie ist grob: 20 % der verheimlichten oder zu niedrig angegebenen Bemessungsgrundlage nach Artikel 223 des Steuergesetzbuchs, angewandt, wenn Waren oder Dienstleistungen ohne Ausstellung einer elektronischen Rechnung verkauft werden oder die Rechnung verspätet ausgestellt wird. Die Durchsetzung begann am 1. April 2021, verschoben vom 1. März, und ab diesem Datum konnten Steuerpflichtige Rechnungen für frühere Zeiträume nur noch nachträglich ausstellen, wenn sie die 20-%-Belastung in Kauf nahmen. Eine wissenswerte Nuance: Usbekische Steuerpraktiker argumentieren, dass Artikel 223 eine Verheimlichungsvorschrift und keine Vorschrift über Dokumentationsformalitäten ist und daher nicht greifen sollte, wenn eine Rechnung nach Monatsende rechtmäßig innerhalb der Fristen der Verordnung 489 ausgestellt wird, da keine steuerliche Verzerrung entsteht. Der Wert von 20 % wird durch zwei unabhängige usbekische Quellen bestätigt, doch der Wortlaut des Artikels konnte in dieser Rechercherunde nicht direkt gelesen werden — lex.uz liefert das Steuergesetzbuch als ein einziges sehr großes Dokument, dessen Artikeltext nicht angezeigt wurde.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🚦 Risikobewertung: keine Geldbuße, aber Ihr Käufer bezahlt sie mit seiner Liquidität', NULL, NULL, 'Das System, das am 1. Januar 2026 nach Artikel 4 des Präsidialdekrets UP-153 in Betrieb ging, sieht überhaupt keine Strafe vor, weshalb es leicht unterschätzt wird. Jede Rechnung wird in Echtzeit anhand von Kriterien bewertet, die das Steuerkomitee bewusst geheim hält — Berichten zufolge 48 an der Zahl, auf Rat internationaler Fachleute zurückgehalten, um ein Ausnutzen des Systems zu verhindern — und rot oder grün markiert, wobei der Status für den Käufer sichtbar ist. Daraus folgen zwei Konsequenzen. Die markierten Rechnungen eines Steuerpflichtigen dürfen 10 % aller in einem Meldezeitraum ausgestellten Rechnungen nicht überschreiten. Und die Vorsteuer aus einer markierten Rechnung wird erst dann abziehbar, wenn die Steuer tatsächlich vom Verkäufer oder vom Käufer in den Haushalt eingezahlt wurde, was Käufer in der Praxis dazu drängt, entweder auf ihren Lieferanten zu warten oder die Steuer selbst zu zahlen. Wirtschaftlich bedeutet das: Ihr Risikostatus wird zum Problem Ihrer Kunden und damit zu Ihrem eigenen. Beim Start genannte Pilotzahlen: 281 Unternehmen, 5,9 Billionen Sum an Rechnungen und 706 Milliarden Sum an strittigem Vorsteuerabzug im Zeitraum Juli bis September 2025.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '💳 Angrenzende Sanktionen ab 2026, und was wir nicht bestätigen konnten', NULL, NULL, 'Das Gesetz ZRU-1108 führte zum 1. Januar 2026 zwei angrenzende Bußgelder ein, die keine E-Rechnungs-Sanktionen sind, aber nahe genug liegen, um sie zu kennen: UZS 5.000.000 für den Handel ohne die vorgeschriebenen elektronischen Zahlungssysteme und QR-Codes sowie UZS 20.000.000 für die Nutzung der QR-Codes eines anderen Steuerpflichtigen. Beide stammen aus einer Mandanteninformation einer Beratungsgesellschaft und nicht aus dem Gesetzestext. Vier Punkte aus dieser Rechercherunde werden gekennzeichnet, statt als gesicherte Tatsache dargestellt zu werden: Der Wortlaut des Artikels 223 des Steuergesetzbuchs konnte nicht gelesen werden; Anhang 2 zur Verordnung 489, die maßgebliche Verfahrensvorschrift, konnte nicht vollständig abgerufen werden; das JSON-Rechnungsformat stützt sich auf übereinstimmende Sekundärquellen, ohne dass eine primäre technische Spezifikation gefunden wurde; und die beiden soliq.uz-Webangebote sind für automatisierte Abfragen durch robots gesperrt, sodass ihre aktuelle Verfügbarkeit nicht unabhängig überprüft wurde.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Prüfen Sie, ob Sie überhaupt elektronische Rechnungen ausstellen', 'Die Pflicht gilt universell für Unternehmen, und zwar seit dem 1. Januar 2020 — es gibt keine Schwelle, unter die man fallen könnte, und keine verbleibende Einführungsphase. Wenn ein Teil Ihres usbekischen Geschäfts noch auf Papier läuft, ist das ein akutes Risiko nach Artikel 223 und keine bevorstehende Frist.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'UZ' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Besorgen Sie eine digitale ETsP-Signatur und wählen Sie einen Kanal', 'Sie benötigen ein Signaturzertifikat vom Schlüsselzentrum der Steuerbehörde sowie entweder ein Konto auf der staatlichen Plattform oder ein Konto bei einem der 27 registrierten Betreiber. Da der staatliche Roaming-Betreiber zwischen den Betreibern vermittelt, schneidet Sie die Wahl eines privaten Anbieters von keiner Gegenpartei ab.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'UZ' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Nehmen Sie die Annahmefrist des Käufers in Ihren eigenen Prozess auf', 'Der Käufer hat zehn Tage Zeit, um zu bestätigen oder zurückzuweisen; nach Ablauf dieser Frist ist die Zurückweisung nicht mehr möglich und Sie können die Rechnung nicht mehr stornieren. Für Rechnungen über digital gekennzeichnete Waren gilt eine Ein-Tages-Frist mit automatischer Bestätigung. Fordern Sie die Annahme aktiv ein, statt Schweigen als Zustimmung zu werten.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'UZ' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Behandeln Sie Ihren Risikostatus als kaufmännisches und nicht nur als steuerliches Thema', 'Seit Januar 2026 werden Ihre Rechnungen bewertet und markiert, und eine markierte Rechnung verzögert den Vorsteuerabzug Ihres Kunden. Beobachten Sie Ihre Markierungsquote im Verhältnis zur 10-%-Grenze und rechnen Sie damit, dass Käufer danach zu fragen beginnen. Die Kriterien sind bewusst geheim, sodass die Sorgfaltsprüfung von Lieferanten und Geschäftspartnern die einzige wirksame Kontrolle ist.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'UZ' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Prüfen Sie die vorausgefüllte Umsatzsteuererklärung innerhalb von fünf Werktagen', 'Seit Januar 2026 erstellt die Steuerbehörde Ihre Umsatzsteuererklärung und Ihre Erklärung zur Umsatzabgabe aus Ihrem eigenen Rechnungsstrom, und Sie haben fünf Werktage Zeit, sie zu korrigieren. Stimmen Sie laufend ab statt erst zum Abgabezeitpunkt — wenn die Erklärung erscheint, sind die zugrunde liegenden Daten bereits die Version der Behörde.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'UZ' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Staatliches Steuerkomitee — offizielles Portal (gov.uz)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'UZ' AND pt.url = 'https://gov.uz/en/soliq';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'lex.uz — Verordnung Nr. 522 vom 25. Juni 2019, das Gründungsinstrument' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'UZ' AND pt.url = 'https://lex.uz/en/docs/4386771';

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'uz-res-522-2019', 'de',
  'Die Verordnung des Ministerkabinetts Nr. 522 begründet das elektronische Rechnungssystem ESF',
  'Die Verordnung Nr. 522 vom 25. Juni 2019 „Über Maßnahmen zur Verbesserung der Verwendung elektronischer Rechnungen im System der gegenseitigen Verrechnung" ist das Gründungsinstrument von Usbekistans elektronischem Rechnungssystem (ESF / электрон счёт-фактура). Ihr Text macht die elektronische Rechnungsstellung ab dem 1. Juli 2019 freiwillig und ab dem 1. Januar 2020 für alle Unternehmen verpflichtend. Sie benennt außerdem das der Steuerbehörde unterstellte Staatsunternehmen „Yangi Texnologiyalar" (Neue Technologien) als autorisierten Roaming-Betreiber, der für die zentrale Speicherung und für die Übermittlung zwischen konkurrierenden privaten Betreibern zuständig ist — der Knotenpunkt, der Usbekistans Mehrbetreibermodell interoperabel statt fragmentiert macht.',
  '["Heute ist kein Handeln erforderlich — dies ist die historische Rechtsgrundlage, zitiert, damit das Mandat von 2020 einen nachvollziehbaren Ursprung hat", "Wenn Sie den maßgeblichen Text benötigen: lex.uz führt die Verordnung 522 auf Russisch mit einem englischen Deckblatt"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'uz-mandate-2020', 'de',
  'Die elektronische Rechnungsstellung wird für alle Unternehmen verpflichtend',
  'Seit dem 1. Januar 2020 sind elektronische Rechnungen für alle Wirtschaftssubjekte in Usbekistan verbindlich, nach einer sechsmonatigen freiwilligen Phase ab dem 1. Juli 2019. Dies ist das Ankerdatum für Usbekistans Mandat und der Grund, warum das Land in diesen Tracker gehört: eine landesweite, universelle B2B-E-Rechnungspflicht, die seit über sechs Jahren in Kraft ist. Rechnungen werden über das staatliche System oder über einen der registrierten privaten Betreiber ausgetauscht, vom Verkäufer mit einer digitalen Signatur (ETsP) unterzeichnet und anschließend vom Käufer bestätigt oder zurückgewiesen — der ebenfalls signiert. Papierrechnungen bestehen nur für Geschäfte fort, die Staatsgeheimnisse berühren.',
  '["Wenn Sie in Usbekistan B2B handeln, fallen Sie bereits in den Anwendungsbereich — für die E-Rechnungspflicht selbst gibt es keine Umsatzschwelle", "Beschaffen Sie ein digitales ETsP-Signaturzertifikat über das Schlüsselzentrum der Steuerbehörde", "Wählen Sie zwischen der staatlichen Plattform und einem registrierten privaten Betreiber — die Interoperabilität zwischen beiden übernimmt der staatliche Roaming-Betreiber, sodass die Wahl Sie von keiner Gegenpartei ausschließt"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'uz-res-489-2020', 'de',
  'Die Verordnung Nr. 489 legt die Betriebsregeln fest: Rechnungszeitpunkt und die 10-Tage-Frist des Käufers',
  'Die Verordnung des Ministerkabinetts Nr. 489 vom 14. August 2020 enthält in ihrem Anhang 2 die Regelung, die die tägliche ESF-Praxis tatsächlich bestimmt: die Form der Rechnung sowie ihre Ausfüllung, Übermittlung und Annahme. Sie legt die allgemeine Regel fest, dass eine Rechnung auf den Tag der Lieferung oder der Leistungserbringung zu datieren ist, dazu die besondere Monatsregel für fortlaufende Leistungen (Ausstellung bis zum 10. Tag des Folgemonats) sowie die 10-Tage-Frist des Käufers zur Annahme oder Zurückweisung. Hinweis für alle, die dies mit Branchenkommentaren abgleichen: Die Regel zum „10. Tag" wird häufig und fälschlich einer Verordnung von 2025 zugeschrieben — ihr Ursprung liegt hier, im Jahr 2020.',
  '["Bauen Sie die zehntägige Annahmefrist des Käufers in Ihren Prozess ein — nach ihrem Ablauf ist die Zurückweisung nicht mehr möglich und der Verkäufer kann die Rechnung nicht mehr stornieren", "Für Rechnungen über digital gekennzeichnete Waren gilt eine deutlich kürzere Frist: bestätigen oder zurückweisen innerhalb eines Kalendertages, sonst bestätigt das System automatisch"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'uz-risk-scoring-2026', 'de',
  'Die automatisierte Risikoanalyse aller elektronischen Rechnungen in Echtzeit beginnt',
  'Artikel 4 des Präsidialdekrets Nr. UP-153 vom 4. September 2025 wies das Steuerkomitee an, ab dem 1. Januar 2026 eine automatisierte Risikoanalyse in Echtzeit für jede in Usbekistan ausgestellte elektronische Rechnung einzuführen. Rechnungen werden anhand nicht offengelegter Kriterien bewertet und markiert; daraus folgen zwei Konsequenzen. Rechnungen mit hohem Risiko dürfen 10 % aller Rechnungen, die ein Steuerpflichtiger in einem Meldezeitraum ausstellt, nicht überschreiten, und die Vorsteuer aus einer Rechnung mit hohem Risiko wird erst dann abziehbar, wenn die Steuer tatsächlich vom Verkäufer oder vom Käufer in den Haushalt eingezahlt wurde. Das System wurde mit technischer Unterstützung des IWF und des CCAMTAC entwickelt. Wichtig: Es blockiert Rechnungen nicht — eine markierte Rechnung ist weiterhin wirksam ausgestellt, und die Folge trifft den Zeitpunkt des Vorsteuerabzugs beim Käufer.',
  '["Käufer: Prüfen Sie den Risikostatus eingehender Rechnungen, bevor Sie sich auf den Vorsteuerabzug verlassen — eine markierte Rechnung verschiebt die Erstattung, sie verweigert sie nicht", "Verkäufer: Beobachten Sie Ihre eigene Quote markierter Rechnungen im Verhältnis zur 10-%-Grenze", "Die Kriterien werden bewusst nicht veröffentlicht, sodass sich das System nicht gezielt umgehen lässt — die eigentliche Kontrolle ist die Sorgfaltsprüfung Ihrer Lieferanten"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'uz-self-employed-2026', 'de',
  'Selbstständige werden in die Rechnungspflicht einbezogen; Steuererklärungen werden aus Rechnungsdaten vorausgefüllt',
  'Das Gesetz Nr. ZRU-1108 vom 25. Dezember 2025, in Kraft seit dem 1. Januar 2026, erstreckt die Rechnungspflicht auf Selbstständige und stellt sie damit juristischen Personen und Einzelunternehmern gleich — eine echte Ausweitung des Kreises der Ausstellungspflichtigen. Dasselbe Gesetz führt etwas ein, das wohl noch bedeutsamer ist: Die Steuerbehörde erstellt die Umsatzsteuererklärungen und die Erklärungen zur Umsatzabgabe nun automatisch aus den ESF-Daten und räumt den Steuerpflichtigen fünf Werktage zur Korrektur ein. Ab diesem Punkt ist Usbekistans Rechnungsstrom kein Nebenprodukt der Compliance mehr, sondern die Steuererklärung selbst.',
  '["Selbstständige, die mit Unternehmen handeln: Sie fallen nun in den Anwendungsbereich und benötigen eine digitale Signatur sowie ein Konto bei einem Betreiber oder auf der staatlichen Plattform", "Alle Steuerpflichtigen: Prüfen Sie die vorausgefüllte Umsatzsteuererklärung innerhalb der gewährten fünf Werktage — Schweigen gilt als Zustimmung", "Gleichen Sie Ihre eigenen Bücher laufend mit dem Rechnungsstrom ab statt erst zum Abgabezeitpunkt, da der Strom nun die Erklärung bestimmt"]'
);

INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES (
  '2026-07-29-uzbekistan-ai-soliq', 'de',
  'Usbekistan baut einen Chatbot, der die Rechnungsrisiko-Bewertungen erklärt, die es nicht veröffentlichen will',
  'Usbekistans Steuerkomitee hat AI SOLIQ gestartet, eine KI-Plattform auf Basis des eigenen Modells „Soliq LLM". Die für Unternehmen folgenreichste Funktion: Steuerpflichtige können das System nun fragen, warum eine bestimmte elektronische Rechnung unter dem seit Januar 2026 laufenden Echtzeit-Bewertungssystem als hochriskant markiert wurde — nach Kriterien, die ansonsten bewusst nicht veröffentlicht werden.',
  '<h3>🇺🇿 Usbekistan baut einen Chatbot, der die Rechnungsrisiko-Bewertungen erklärt, die es nicht veröffentlichen will</h3>
<p>Am 29. Juli 2026 stellte Usbekistans Steuerkomitee AI SOLIQ vor, eine einheitliche Plattform für künstliche Intelligenz auf Basis von „Soliq LLM", seinem eigenen Sprachmodell, mit Komponenten für Text- und Spracherzeugung, Computer Vision und maschinelles Lernen.</p>
<p>Die Funktion, die für alle, die in Usbekistan Handel treiben, am wichtigsten ist, fällt schmaler aus, als die Ankündigung vermuten lässt. Seit dem 1. Januar 2026 wird jede im Land ausgestellte elektronische Rechnung nach Artikel 4 des Präsidialdekrets UP-153 in Echtzeit auf Risiken bewertet und rot oder grün markiert. Die Kriterien — Berichten zufolge 48 an der Zahl — werden auf Rat internationaler Fachleute bewusst zurückgehalten, um zu verhindern, dass Steuerpflichtige das System ausnutzen. Diese Geheimhaltung ist als Missbrauchsabwehr vertretbar und als Kundenservice unbeholfen: Ein Unternehmen konnte eine markierte Rechnung sehen, ohne jede Möglichkeit herauszufinden, warum.</p>
<p>AI SOLIQ ist die Antwort darauf. Steuerpflichtige können nun mit dem System einen Dialog darüber führen, warum eine bestimmte Rechnung als rot eingestuft wurde, ergänzt um Erläuterungen zu ihrem Steuerrating und ihren Erklärungspflichten. Es geht dabei um Handfestes und nicht um Reputation: Die Vorsteuer aus einer markierten Rechnung wird erst dann abziehbar, wenn die Steuer tatsächlich im Haushalt eingegangen ist, sodass der Risikostatus eines Lieferanten unmittelbar die Liquidität seiner Kunden verzögert.</p>
<p>Es ist eine bemerkenswerte Abfolge — eine Steuerverwaltung, die das Rechnungsrisiko zunächst folgenreich und unerklärt machte und dann ein Sprachmodell baute, um es zu erklären — und sie ist es wert, beobachtet zu werden, während andere Freigabe- und CTC-Jurisdiktionen eigene Bewertungsebenen hinzufügen.</p>'
);


-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr',
  'Contrôle continu des transactions (CTC) centralisé : facturation électronique B2B universelle depuis 2020, échangée via la plateforme étatique ou un opérateur enregistré, l''acheteur faisant office de point de validation — et non un régime de dédouanement préalable',
  'Cette page d''analyse reflète la législation ouzbèke telle que publiée sur lex.uz et sur le portail propre du Comité d''État des impôts (gov.uz), complétée par la presse spécialisée ouzbèke en matière juridique et fiscale lorsque les annexes primaires n''ont pas pu être récupérées intégralement, à la date du 10 août 2026. Elle est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Plusieurs éléments sont explicitement signalés sur cette page comme non confirmés plutôt que présentés comme acquis — veuillez lire ces notes. Confirmez les exigences en vigueur directement auprès du Comité des impôts de l''Ouzbékistan, de votre opérateur ESF ou d''un conseiller fiscal ouzbek avant de fonder vos décisions de conformité sur cette page.',
  'Le régime de facture électronique ESF de l''Ouzbékistan a été créé par la résolution du Cabinet des ministres n° 522 du 25 juin 2019 : facultatif à partir du 1er juillet 2019, obligatoire pour toutes les entités commerciales à partir du 1er janvier 2020. La résolution n° 489 d''août 2020 a fixé les règles de fonctionnement toujours en vigueur. Deux changements sont intervenus le 1er janvier 2026 — la notation du risque des factures en temps réel et l''extension de l''obligation aux travailleurs indépendants.',
  'Une facture électronique ouzbèke conforme est un document électronique structuré, signé par le vendeur au moyen d''une signature numérique ETsP et contresigné par l''acheteur lors de son acceptation. Elle est échangée soit via la plateforme étatique, soit via l''un des opérateurs privés EDO enregistrés, l''interopérabilité entre opérateurs étant assurée par l''opérateur de roaming désigné par l''État, l''entreprise publique « Yangi Texnologiyalar ». Les lignes de produits et de services portent des codes de classification ITSPU issus du catalogue électronique national.',
  'L''obligation est universelle pour les entités commerciales et n''est pas liée au seuil de TVA : toute entité économique doit émettre des factures électroniques, qu''elle soit ou non assujettie à la TVA. Les travailleurs indépendants y ont été intégrés à compter du 1er janvier 2026. Les factures papier ne subsistent que lorsque l''opération touche à des secrets d''État. Les ventes aux consommateurs particuliers se situent en pratique en dehors du circuit d''échange électronique et relèvent des caisses enregistreuses en ligne.',
  'Si vous commercez en B2B en Ouzbékistan, vous êtes déjà dans le champ d''application, et ce depuis 2020 — il ne reste aucune phase de déploiement à préparer. Le vrai chantier consiste à s''adapter aux deux changements de janvier 2026 : le système de notation du risque, qui détermine à quel moment vos acheteurs peuvent récupérer la TVA en amont sur vos factures, et les déclarations pré-remplies générées à partir de votre propre flux de factures.',
  'L''Ouzbékistan adosse son obligation à une seule sanction chiffrée — 20 % de la base imposable dissimulée, au titre de l''article 223 du Code fiscal — plutôt qu''à un barème publié d''amendes forfaitaires. Le système de notation du risque de 2026 ne comporte aucune sanction ; sa conséquence est le report du droit à déduction de la TVA en amont pour l''acheteur.',
  'L''Ouzbékistan impose des factures électroniques à toutes les entités commerciales depuis le 1er janvier 2020, en vertu de la résolution du Cabinet des ministres n° 522. Les factures sont échangées via la plateforme étatique ou un opérateur privé enregistré, signées numériquement par le vendeur et confirmées par l''acheteur dans un délai de dix jours. Depuis le 1er janvier 2026, chaque facture fait l''objet d''une notation du risque en temps réel, la TVA en amont d''une facture signalée n''étant déductible qu''une fois la taxe versée au budget, et l''administration fiscale pré-remplit désormais les déclarations de TVA directement à partir du flux de factures.',
  '🇺🇿'
FROM countries WHERE code = 'UZ';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er janv. 2020', 'La facturation électronique devient obligatoire pour toutes les entités commerciales' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'UZ' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '~3,5 millions', 'Factures électroniques émises chaque mois (chiffre communiqué en octobre 2025)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'UZ' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '27', 'Opérateurs ESF inscrits au registre du Comité des impôts (janvier 2026)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'UZ' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '209 000', 'Assujettis à la TVA, chiffre cité lors de la réunion présidentielle sur la fiscalité d''avril 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'UZ' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '12 %', 'Taux normal de TVA, avec un taux simplifié optionnel de 6 % à partir de juin 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'UZ' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Format et transmission', '[["Format de la facture", "Document électronique structuré, rapporté comme étant du JSON"], ["Signature", "Signature numérique ETsP — bilatérale : le vendeur signe pour émettre, l''acheteur signe pour accepter"], ["Canaux", "La plateforme étatique, ou l''un des 27 opérateurs privés EDO enregistrés"], ["Interopérabilité", "Assurée par l''opérateur de roaming désigné par l''État, l''entreprise publique \"Yangi Texnologiyalar\" (résolution 522)"], ["Codes de classification", "Codes ITSPU issus du catalogue électronique national, qui comptait plus de 454 500 codes en septembre 2024"], ["Normes européennes", "Pas EN 16931 ; l''Ouzbékistan n''est pas une autorité Peppol"]]', 'Le format JSON est indiqué de manière cohérente par plusieurs sources secondaires indépendantes, mais aucune spécification technique primaire n''a pu être localisée lors de cette série de recherches — considérez le nom du format comme bien étayé plutôt que comme confirmé.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Conservation : deux horloges distinctes', '[["Opérateurs", "Doivent conserver les documents électroniques confirmés pendant au moins 5 ans, après quoi l''archivage passe à l''administration fiscale"], ["Contribuables", "La conservation générale des documents comptables et fiscaux a été ramenée de 5 à 3 ans à compter du 1er janvier 2024 par la loi n° ZRU-891, alignée sur le délai de prescription de l''article 88 du Code fiscal"], ["Durées plus longues", "Les registres d''immobilisations et d''amortissements sont conservés plus longtemps"]]', 'Il s''agit d''obligations réellement distinctes, souvent confondues. Le fait que votre opérateur conserve une facture pendant cinq ans ne prolonge pas votre propre obligation de conservation de trois ans, et votre obligation de trois ans ne raccourcit pas la sienne.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Qui doit émettre des factures électroniques', '[["Toutes les entités commerciales", "Obligatoire depuis le 1er janvier 2020 en vertu de la résolution 522 — aucun seuil de chiffre d''affaires sur l''obligation elle-même"], ["Travailleurs indépendants", "Intégrés à compter du 1er janvier 2026 par la loi n° ZRU-1108, sur un pied d''égalité avec les personnes morales et les entrepreneurs individuels"], ["B2G", "Dans le champ d''application"], ["B2C", "Pas un échange électronique en pratique — voir la note"], ["Seule exemption trouvée", "Les opérations touchant à des secrets d''État, pour lesquelles les factures papier en au moins deux exemplaires restent autorisées"]]', 'Le champ d''application B2C fait réellement débat. Deux sources internationales de conformité classent le B2C dans le champ d''application, mais les guides des praticiens ouzbeks indiquent que, pour les ventes aux consommateurs particuliers, le vendeur imprime et remet le document, le circuit électronique ne s''appliquant pas — le commerce de détail relevant plutôt des caisses enregistreuses en ligne et des obligations de paiement par code QR. Cette page n''affirme pas l''existence d''une obligation de facturation électronique B2C.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🔍 Pourquoi cette page ne qualifie pas l''Ouzbékistan de régime de dédouanement', NULL, NULL, 'Une brochure sectorielle largement diffusée présente l''Ouzbékistan comme un modèle de dédouanement en temps réel dans lequel l''administration fiscale valide une facture avant qu''elle ne devienne juridiquement définitive. Les éléments disponibles pointent dans une autre direction : cette page le décrit donc autrement et explique pourquoi. Le flux documenté va du vendeur à l''acheteur, et non du vendeur à l''administration fiscale puis à l''acheteur : le vendeur signe et transmet, puis l''acheteur certifie avec sa propre signature ou refuse en indiquant les motifs, dans un délai de dix jours au terme duquel l''option de refus se désactive. Un délai d''acceptation par l''acheteur est la signature d''un modèle d''échange. Le système de risque de 2026 renforce ce constat — il colore les factures au lieu de les bloquer, et une facture signalée reste valablement émise, la conséquence portant sur le calendrier de déduction de la TVA en amont de l''acheteur et non sur la validité de la facture. Sous un véritable dédouanement préalable, une facture rejetée n''existerait tout simplement pas. Il existe un point de contrôle technique à l''enregistrement et, depuis 2026, un point de contrôle du risque affectant le crédit de TVA, mais pas de point de contrôle d''approbation fiscale suspendant la validité juridique dans l''attente du feu vert de l''administration. Une réserve supplémentaire, énoncée plutôt que dissimulée : l''annexe 2 de la résolution 489, qui porte la procédure opérationnelle, n''a pas pu être récupérée intégralement auprès d''une source primaire lors de cette série de recherches ; la description du flux ci-dessus repose donc sur une presse juridique spécialisée ouzbèke de grande qualité plutôt que sur le texte légal.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Le flux d''échange', 'Une facture électronique ouzbèke suit la séquence suivante :', 'L''étape décisive est celle de l''acheteur, et non celle de l''administration fiscale — c''est la raison pour laquelle cette page décrit l''Ouzbékistan comme un échange centralisé plutôt que comme un régime de dédouanement.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND lc.section = 'scope_transmission' AND lc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Le vendeur génère la facture et la signe avec une signature numérique ETsP' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND ls.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Transmission via la plateforme étatique ou un opérateur enregistré, avec routage inter-opérateurs par l''opérateur de roaming étatique' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'À partir de 2026 : notation du risque en temps réel et signalement, mais pas de blocage' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'L''acheteur certifie avec sa propre signature, ou refuse en indiquant les motifs, dans un délai de 10 jours' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Les marchandises à marquage numérique suivent une horloge bien plus courte : confirmer ou refuser dans un délai d''un jour calendaire, sinon la facture est confirmée automatiquement' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'UZ' AND ls.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '⚠️ L''unique sanction chiffrée : l''article 223 du Code fiscal', NULL, NULL, 'L''Ouzbékistan ne publie pas de barème d''amendes forfaitaires pour les manquements de format, de transmission ou d''acceptation en matière de facturation électronique. Il dispose d''une seule sanction chiffrée, et elle est brutale : 20 % de la base imposable dissimulée ou minorée, au titre de l''article 223 du Code fiscal, appliquée lorsque des biens ou des services sont vendus sans qu''une facture électronique soit émise, ou lorsqu''elle est émise tardivement. L''application a débuté le 1er avril 2021, reportée du 1er mars, et à compter de cette date les contribuables ne pouvaient émettre rétroactivement des factures pour des périodes antérieures qu''en acceptant la charge de 20 %. Une nuance utile à connaître : les praticiens fiscaux ouzbeks soutiennent que l''article 223 est une disposition relative à la dissimulation et non aux formalités documentaires, et qu''il ne devrait donc pas s''appliquer lorsqu''une facture est légalement émise après la fin du mois dans les délais de la résolution 489, puisqu''aucune distorsion fiscale n''en résulte. Le chiffre de 20 % est corroboré par deux sources ouzbèkes indépendantes, mais le texte littéral de l''article n''a pas pu être lu directement lors de cette série de recherches — lex.uz diffuse le Code fiscal comme un document unique très volumineux qui n''affichait pas le corps de l''article.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🚦 Notation du risque : pas d''amende, mais votre acheteur la paie en trésorerie', NULL, NULL, 'Le système entré en service le 1er janvier 2026 en vertu de l''article 4 du décret présidentiel UP-153 ne comporte absolument aucune sanction, ce qui le rend facile à sous-estimer. Chaque facture est notée en temps réel au regard de critères que le Comité des impôts a délibérément gardés secrets — 48 d''entre eux selon les informations disponibles, non divulgués sur les conseils d''experts internationaux afin d''empêcher tout contournement — et signalée en rouge ou en vert, le statut étant visible par l''acheteur. Deux conséquences en découlent. Les factures signalées d''un contribuable ne doivent pas dépasser 10 % de l''ensemble des factures émises au cours d''une période déclarative. Et la TVA en amont d''une facture signalée ne devient déductible qu''une fois la taxe effectivement versée au budget par le vendeur ou par l''acheteur, ce qui pousse en pratique les acheteurs soit à attendre leur fournisseur, soit à acquitter eux-mêmes la TVA. L''effet commercial est que votre situation de risque devient le problème de vos clients, et donc le vôtre. Chiffres du pilote cités au lancement : 281 entreprises, 5 900 milliards de sum de factures et 706 milliards de sum de crédit de TVA en jeu entre juillet et septembre 2025.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '💳 Sanctions connexes de 2026, et ce que nous n''avons pas pu confirmer', NULL, NULL, 'La loi ZRU-1108 a introduit, à compter du 1er janvier 2026, deux amendes connexes qui ne sont pas des sanctions de facturation électronique mais en sont assez proches pour mériter d''être connues : UZS 5 000 000 pour l''exercice d''une activité sans les systèmes de paiement électronique et les codes QR obligatoires, et UZS 20 000 000 pour l''utilisation des codes QR d''un autre contribuable. Les deux proviennent d''une alerte de cabinet de services professionnels et non du texte légal. Quatre éléments issus de cette série de recherches sont signalés plutôt que présentés comme des faits acquis : le texte littéral de l''article 223 du Code fiscal n''a pas pu être lu ; l''annexe 2 de la résolution 489, le règlement de procédure opérationnelle, n''a pas pu être récupérée intégralement ; le format de facture JSON repose sur des sources secondaires cohérentes sans qu''aucune spécification technique primaire n''ait été localisée ; et les deux sites web de soliq.uz sont bloqués aux vérifications automatisées par robots, de sorte que leur disponibilité actuelle n''a pas été vérifiée de manière indépendante.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'UZ' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez que vous émettez bel et bien des factures électroniques', 'L''obligation est universelle pour les entités commerciales, et ce depuis le 1er janvier 2020 — il n''existe aucun seuil sous lequel se situer et aucune phase de déploiement restante. Si une partie de votre activité ouzbèke est encore sur papier, il s''agit d''une exposition immédiate au titre de l''article 223, et non d''une échéance à venir.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'UZ' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Obtenez une signature numérique ETsP et choisissez un canal', 'Il vous faut un certificat de signature numérique délivré par le centre de clés de l''administration fiscale, ainsi qu''un compte sur la plateforme étatique ou un compte auprès de l''un des 27 opérateurs enregistrés. Comme l''opérateur de roaming étatique assure le routage entre opérateurs, choisir un opérateur privé ne vous coupe d''aucune contrepartie.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'UZ' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Intégrez le délai d''acceptation de l''acheteur à votre propre processus', 'L''acheteur dispose de dix jours pour certifier ou refuser et, une fois ce délai écoulé, l''option de refus se désactive et vous ne pouvez plus annuler la facture. Les factures portant sur des marchandises à marquage numérique suivent une horloge d''un jour avec confirmation automatique. Relancez pour obtenir l''acceptation plutôt que de considérer le silence comme un accord.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'UZ' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Traitez votre situation de risque comme un enjeu commercial, et pas seulement fiscal', 'Depuis janvier 2026, vos factures sont notées et signalées, et une facture signalée retarde la récupération de la TVA en amont de votre client. Surveillez votre proportion de factures signalées au regard du plafond de 10 %, et attendez-vous à ce que les acheteurs commencent à s''en enquérir. Les critères sont secrets par conception, de sorte que la diligence raisonnable sur les fournisseurs et les contreparties est le seul véritable contrôle.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'UZ' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Examinez la déclaration de TVA pré-remplie dans les cinq jours ouvrables', 'Depuis janvier 2026, l''administration fiscale établit vos déclarations de TVA et d''impôt sur le chiffre d''affaires à partir de votre propre flux de factures, et vous disposez de cinq jours ouvrables pour les corriger. Rapprochez vos comptes en continu plutôt qu''au moment du dépôt — lorsque la déclaration apparaît, les données sous-jacentes sont déjà la version des faits retenue par l''administration.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'UZ' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Comité d''État des impôts — portail officiel (gov.uz)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'UZ' AND pt.url = 'https://gov.uz/en/soliq';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'lex.uz — résolution n° 522 du 25 juin 2019, l''instrument fondateur' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'UZ' AND pt.url = 'https://lex.uz/en/docs/4386771';

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'uz-res-522-2019', 'fr',
  'La résolution du Cabinet des ministres n° 522 institue le régime de facture électronique ESF',
  'La résolution n° 522 du 25 juin 2019, « Sur les mesures visant à améliorer l''utilisation des factures électroniques dans le système de règlements mutuels », est l''instrument fondateur du régime de facture électronique (ESF / электрон счёт-фактура) de l''Ouzbékistan. Son texte rend la facturation électronique facultative à partir du 1er juillet 2019 et obligatoire à partir du 1er janvier 2020 pour toutes les entités commerciales. Il désigne également l''entreprise publique « Yangi Texnologiyalar » (Nouvelles Technologies), placée sous l''autorité de l''administration fiscale, comme opérateur de roaming agréé, chargé du stockage centralisé et de la transmission entre opérateurs privés concurrents — le nœud qui rend le modèle multi-opérateurs de l''Ouzbékistan interopérable plutôt que fragmenté.',
  '["Aucune action n''est requise aujourd''hui — il s''agit du fondement juridique historique, cité pour que l''obligation de 2020 ait une origine traçable", "Si vous avez besoin du texte opérationnel, lex.uz publie la résolution 522 en russe avec une page de garde en anglais"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'uz-mandate-2020', 'fr',
  'La facturation électronique devient obligatoire pour toutes les entités commerciales',
  'Depuis le 1er janvier 2020, les factures électroniques sont obligatoires pour toutes les entités économiques d''Ouzbékistan, après une phase volontaire de six mois entamée le 1er juillet 2019. C''est la date de référence de l''obligation ouzbèke et la raison pour laquelle le pays a sa place dans ce suivi : une obligation de facturation électronique B2B universelle et nationale, en vigueur depuis plus de six ans. Les factures sont échangées via le système étatique ou via l''un des opérateurs privés enregistrés, signées par le vendeur au moyen d''une signature numérique (ETsP), puis confirmées ou refusées par l''acheteur — qui signe lui aussi. Les factures papier ne subsistent que pour les opérations touchant à des secrets d''État.',
  '["Si vous commercez en B2B en Ouzbékistan, vous êtes déjà dans le champ d''application — il n''existe aucun seuil de chiffre d''affaires sur l''obligation de facturation électronique elle-même", "Obtenez un certificat de signature numérique ETsP auprès du centre de clés de l''administration fiscale", "Choisissez entre la plateforme étatique et un opérateur privé enregistré — l''interopérabilité entre les deux est assurée par l''opérateur de roaming étatique, de sorte que ce choix ne vous coupe d''aucune contrepartie"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'uz-res-489-2020', 'fr',
  'La résolution n° 489 fixe les règles de fonctionnement : calendrier d''émission et délai de 10 jours de l''acheteur',
  'La résolution du Cabinet des ministres n° 489 du 14 août 2020 contient, dans son annexe 2, la réglementation qui régit réellement la pratique quotidienne de l''ESF : la forme de la facture, ainsi que la manière dont elle est renseignée, transmise et acceptée. Elle pose la règle générale selon laquelle une facture est datée du jour de l''expédition ou de la prestation, la règle mensuelle particulière applicable aux prestations continues (émission au plus tard le 10e jour du mois suivant) et le délai de 10 jours dont dispose l''acheteur pour accepter ou refuser. Note à l''attention de qui recoupe avec les commentaires sectoriels : la règle du « 10e jour » est fréquemment et à tort attribuée à une résolution de 2025 — son origine se trouve ici, en 2020.',
  '["Intégrez à votre processus le délai d''acceptation de 10 jours de l''acheteur — une fois écoulé, l''option de refus se désactive et le vendeur ne peut plus annuler la facture", "Les factures portant sur des marchandises à marquage numérique suivent une horloge bien plus courte : confirmez ou refusez dans un délai d''un jour calendaire, faute de quoi le système confirme automatiquement"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'uz-risk-scoring-2026', 'fr',
  'L''analyse de risque automatisée et en temps réel de chaque facture électronique commence',
  'L''article 4 du décret présidentiel n° UP-153 du 4 septembre 2025 a chargé le Comité des impôts de déployer, à compter du 1er janvier 2026, une analyse de risque automatisée et en temps réel de chaque facture électronique émise en Ouzbékistan. Les factures sont notées au regard de critères non divulgués puis signalées ; deux conséquences en découlent. Les factures à risque élevé ne doivent pas dépasser 10 % de l''ensemble des factures qu''un contribuable émet au cours d''une période déclarative, et la TVA en amont d''une facture à risque élevé ne devient déductible qu''une fois la taxe effectivement versée au budget par le vendeur ou par l''acheteur. Le système a été développé avec l''assistance technique du FMI et du CCAMTAC. Point important : il ne bloque pas les factures — une facture signalée reste valablement émise, la conséquence portant sur le calendrier de déduction de la TVA de l''acheteur.',
  '["Acheteurs : vérifiez le statut de risque des factures reçues avant de vous fier au crédit de TVA en amont — une facture signalée reporte la récupération, elle ne la refuse pas", "Vendeurs : surveillez votre propre proportion de factures signalées au regard du plafond de 10 %", "Les critères ne sont délibérément pas publiés, ce qui interdit tout contournement — traitez la diligence raisonnable sur les fournisseurs comme le véritable contrôle"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'uz-self-employed-2026', 'fr',
  'Les travailleurs indépendants entrent dans l''obligation de facturation ; les déclarations sont pré-remplies à partir des données de facturation',
  'La loi n° ZRU-1108 du 25 décembre 2025, en vigueur depuis le 1er janvier 2026, étend l''obligation de facturation aux travailleurs indépendants sur un pied d''égalité avec les personnes morales et les entrepreneurs individuels — un véritable élargissement du cercle de ceux qui doivent émettre. La même loi introduit un élément sans doute plus important encore : l''administration fiscale établit désormais automatiquement les déclarations de TVA et d''impôt sur le chiffre d''affaires à partir des données ESF, en laissant aux contribuables cinq jours ouvrables pour les corriger. C''est à ce moment-là que le flux de factures ouzbek cesse d''être un sous-produit de la conformité pour devenir la déclaration elle-même.',
  '["Travailleurs indépendants commerçant avec des entreprises : vous êtes désormais dans le champ d''application et devez disposer d''une signature numérique ainsi que d''un compte auprès d''un opérateur ou sur la plateforme étatique", "Tous les contribuables : examinez la déclaration de TVA pré-remplie dans les cinq jours ouvrables accordés — le silence vaut acceptation", "Rapprochez vos propres livres du flux de factures en continu plutôt qu''au moment du dépôt, puisque ce flux détermine désormais la déclaration"]'
);

INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES (
  '2026-07-29-uzbekistan-ai-soliq', 'fr',
  'L''Ouzbékistan construit un chatbot pour expliquer les scores de risque des factures qu''il refuse de publier',
  'Le Comité des impôts de l''Ouzbékistan a lancé AI SOLIQ, une plateforme d''intelligence artificielle bâtie sur son propre modèle « Soliq LLM ». Sa fonctionnalité la plus lourde de conséquences pour les entreprises : les contribuables peuvent désormais demander au système pourquoi une facture électronique donnée a été signalée comme à risque élevé au titre du régime de notation en temps réel entré en service en janvier 2026 — des critères qui, par ailleurs, restent délibérément non publiés.',
  '<h3>🇺🇿 L''Ouzbékistan construit un chatbot pour expliquer les scores de risque des factures qu''il refuse de publier</h3>
<p>Le 29 juillet 2026, le Comité des impôts de l''Ouzbékistan a dévoilé AI SOLIQ, une plateforme unifiée d''intelligence artificielle bâtie sur « Soliq LLM », son propre modèle de langage propriétaire, dotée de composantes de génération de texte et de parole, de vision par ordinateur et d''apprentissage automatique.</p>
<p>La fonctionnalité qui compte le plus pour quiconque commerce en Ouzbékistan est plus étroite que ne le laisse penser la présentation du lancement. Depuis le 1er janvier 2026, chaque facture électronique émise dans le pays fait l''objet d''une notation du risque en temps réel et d''un signalement en rouge ou en vert, en vertu de l''article 4 du décret présidentiel UP-153. Les critères — 48 d''entre eux selon les informations disponibles — sont délibérément tenus secrets, sur les conseils d''experts internationaux, afin d''empêcher les contribuables de contourner le système. Ce secret se défend comme politique anti-fraude et se révèle malaisé comme service au client : une entreprise pouvait voir une facture signalée sans aucun moyen de savoir pourquoi.</p>
<p>AI SOLIQ est la réponse à cela. Les contribuables peuvent désormais dialoguer avec le système sur les raisons pour lesquelles une facture donnée a été classée en rouge, en plus d''explications sur leur notation fiscale et leurs obligations déclaratives. L''enjeu est bien réel et non pas seulement réputationnel : la TVA en amont d''une facture signalée ne devient déductible qu''une fois la taxe effectivement parvenue au budget, de sorte que la situation de risque d''un fournisseur retarde directement la trésorerie de ses clients.</p>
<p>C''est un enchaînement frappant — une administration fiscale qui a d''abord rendu le risque des factures lourd de conséquences et inexpliqué, puis a construit un modèle de langage pour l''expliquer — et il mérite d''être suivi alors que d''autres juridictions de dédouanement et de CTC ajoutent leurs propres couches de notation.</p>'
);
